import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(System.out); int t = Integer.parseInt(br.readLine()); while (t-- > 0) { long n = Long.parseLong(br.readLine()); long sum = 0; long temp = n; while (temp > 0) { sum += (temp % 10); temp /= 10; } long remainder = sum % 10; long digit = (10 - remainder) % 10; out.println(n * 10 + digit); } out.flush(); out.close(); } }